head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > preventPasteColumn]<br/>GridView 컴포넌트에서 붙여넣기(Ctrl+V)를 차단할 Body Column 을 설정합니다.",
    "validation" : [
        "preventPaste=true 이거나 Body Cell 이 편집모드이면 preventPasteColumn 속성은 무시됩니다.",
        "붙여넣기(Ctrl+V)를 차단할 Body Column 의 ID 를 쉼표(',')로 구분하여 설정합니다.",
        "ID 사이에 공백을 입력하면 Column 매칭에 실패합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 붙여넣기 원본 기본값 설정 (textarea 는 기본값 속성이 없어 setValue 로 설정)
    txa_pasteSource.setValue("붙여넣기값");

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - 편집 가능한 GridView (gBody 4 Column, editType=text), 데이터 4건
//  - preventPasteColumn 은 con_preventPasteColumn 선택값(차단할 Column ID 문자열) 으로 생성
//    · 미설정("") 이면 preventPasteColumn 속성 자체를 제외 → 차단 없음
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    let conPreventPasteColumn = con_preventPasteColumn.getValue();
    let conPreventPaste = con_preventPaste.getText();

    let properties = {
        focusMode : "cell"
    };
    // 미설정("") 일 때는 preventPasteColumn 속성 자체를 제외 (차단 없음)
    if (conPreventPasteColumn !== "") {
        properties.preventPasteColumn = conPreventPasteColumn;
    }
    // preventPaste=true 이면 preventPasteColumn 은 무시되고 전체 Column 붙여넣기가 차단됨
    if (conPreventPaste !== "") {
        properties.preventPaste = conPreventPaste;
    }
    let cList = $c.gcm.createCList(properties);

    // 붙여넣기 이벤트(oncustompaste) 바인딩 (붙여넣기 후 셀 값 출력용)
    let eList = $c.gcm.createEList(["oncustompaste"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblPreventPasteColumn = (conPreventPasteColumn === '') ? '미설정(차단 없음)' : conPreventPasteColumn;
    let lblPreventPaste = (conPreventPaste === '') ? '미설정(기본 false)' : conPreventPaste;
    $c.gcm.createLabel('label="preventPasteColumn=' + lblPreventPasteColumn + ', preventPaste=' + lblPreventPaste + ' 로 편집 가능 GridView 생성. 설정한 Body Column 의 셀은 붙여넣기(Ctrl+V) 시 값이 붙지 않음(차단). ID 사이 공백이 있으면 매칭 실패하여 차단되지 않음. preventPaste=true 이면 preventPasteColumn 은 무시되고 전체 Column 의 붙여넣기가 차단됨"', '', 'label1');

    // dataList 생성 (column id 를 col1~col4 로 맞춤, 붙여넣기 확인용 초기 텍스트 채움)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { col1 : "Origin0_0", col2 : "Origin0_1", col3 : "Origin0_2", col4 : "Origin0_3" },
        { col1 : "Origin1_0", col2 : "Origin1_1", col3 : "Origin1_2", col4 : "Origin1_3" },
        { col1 : "Origin2_0", col2 : "Origin2_1", col3 : "Origin2_2", col4 : "Origin2_3" },
        { col1 : "Origin3_0", col2 : "Origin3_1", col3 : "Origin3_2", col4 : "Origin3_3" }
    ]);

    // target 생성 (편집 가능 그리드 : gBody Column 에 editType="text")
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:480px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="preventPasteColumn 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="col1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="col2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" editType="text"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" editType="text"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" editType="text"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col4" editType="text"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// con_preventPasteColumn 변경 시 Target 재생성 안내 (con 변경은 Target 재생성 버튼으로 반영)
scwin.con_preventPasteColumn_onchange = function () {
    // 별도 동작 없음 (Target 재생성 버튼 클릭 시 comp_init 에서 반영)
}



// 포커스된 그리드 셀의 값 조회
//  - getFocusedRowIndex / getFocusedColumnIndex 로 포커스 셀 위치 → getCellDisplayData 로 셀 값 조회
//  - 포커스 없으면 빈 문자열 반환
scwin.getFocusedCellValue = function () {
    let rowIndex = target1.getFocusedRowIndex();
    let colIndex = target1.getFocusedColumnIndex();
    if (rowIndex === undefined || rowIndex === null || rowIndex < 0 || colIndex === undefined || colIndex === null || colIndex < 0) {
        return "";
    }
    return target1.getCellDisplayData(rowIndex, colIndex);
}



// oncustompaste 핸들러 (셀 선택 후 Ctrl+V 시 발생)
//  - 기본 붙여넣기는 그대로 진행되도록 false 를 반환하지 않음
//  - 붙여넣기 적용 이후(setTimeout 0) 포커스 셀 값을 출력
//    · 차단 Column 의 셀이면 값이 그대로(변화 없음), 비차단 Column 이면 붙여넣은 값으로 변경
scwin.target1_oncustompaste = function (e) {
    let row = target1.getFocusedRowIndex();
    let col = target1.getFocusedColumnIndex();
    setTimeout(function () {
        let bottom = wf_body_bottom.getObj("scwin");
        bottom.btn_clear_onclick();
        bottom.setReturnValue("붙여넣기 대상 셀(row " + row + ", col " + col + ") 값 : " + scwin.getFocusedCellValue());
    }, 0);
}
